import { sendEmail } from './mail.js'
import { pool } from './db.js'

// Runs in the web process. Jobs are lost on restart.
setInterval(async () => {
  const { rows } = await pool.query("select * from outbox where sent_at is null limit 10")
  for (const row of rows) await sendEmail(row)
}, 5000)

